import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        String tasks = next();
        long cool = nextLong();
        long[] freq = new long[26];
        for (int i = 0; i < tasks.length(); i++) freq[tasks.charAt(i) - 'A']++;
        long f = 0, c = 0;
        for (long v : freq) f = Math.max(f, v);
        for (long v : freq) if (v == f) c++;
        System.out.println(Math.max(tasks.length(), (f - 1) * (cool + 1) + c));
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func next() string {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	tasks := next()
	cool := nextInt()
	var freq [26]int64
	for i := 0; i < len(tasks); i++ {
		freq[tasks[i]-'A']++
	}
	f, c := int64(0), int64(0)
	for _, v := range freq {
		f = max(f, v)
	}
	for _, v := range freq {
		if v == f {
			c++
		}
	}
	fmt.Println(max(int64(len(tasks)), (f-1)*(cool+1)+c))
}
